    && SoilDamping && SoilDampingCoef==.00004f && TDensity==DDT_None && !DDTArray
    && Gravity.x==0. && Gravity.y==0. && Gravity.z==0.,
    "P3 retains inactive remote DBC, Wendland H1.8, raw AV.1/eta4e-5 and HG0/SPR0/AS0");
